effect.shader:
#define fragCoord gl_FragCoord.xy
float hash(float n) { return fract(cos(n) * 114514.1919); }
float noise(in vec3 x) {
vec3 p = floor(x);
vec3 f = smoothstep(0.0, 1.0, fract(x));
float n = p.x + p.y * 10.0 + p.z * 100.0;
return mix(
mix(mix(hash(n + 0.0), hash(n + 1.0), f.x), mix(hash(n + 10.0), hash(n + 11.0), f.x), f.y),
mix(mix(hash(n + 100.0), hash(n + 101.0), f.x), mix(hash(n + 110.0), hash(n + 111.0), f.x), f.y), f.z);
}
float fbm(vec3 p) {
float f = 0.5000 * noise(p);
p = mat3(0.00, 1.60, 1.20, -1.60, 0.72, -0.96, -1.20, -0.96, 1.28) * p;
f += 0.2500 * noise(p);
p = mat3(0.00, 1.60, 1.20, -1.60, 0.72, -0.96, -1.20, -0.96, 1.28) * p;
f += 0.1666 * noise(p);
p = mat3(0.00, 1.60, 1.20, -1.60, 0.72, -0.96, -1.20, -0.96, 1.28) * p;
f += 0.0834 * noise(p);
return f;
}
void main() {
vec2 uv = acScreenNorm * 2.0 - 1.0;
uv.x *= acScreenSize.x / acScreenSize.y;
float t = (progressa + 13.5 + 44.) * 1.0;
vec3 campos = vec3(5000.0 * sin(1.0 * t + camx), 5000. + 1500. * sin(0.5 * t + camy), 6000.0 * t + camprog);
vec3 camtar = vec3(5000.0 * sin(1.0 * (t + 0.4) + camx), 5000. + 1500. * sin(0.5 * (t + 0.4) + camy), 6000.0 * (t + 0.4) + camprog);
vec3 front = normalize(camtar - campos);
vec3 right = normalize(cross(front, vec3(0.0, 1.0, 0.0)));
vec3 up = normalize(cross(right, front));
vec3 fragAt = normalize(uv.x * right + uv.y * up + front);
vec4 sum = vec4(0, 0, 0, 0);
for (float depth = 0.0; depth < 100000.0; depth += 200.0) {
vec3 ray = campos + fragAt * depth;
if (0.0 < ray.y && ray.y < 10000.0) {
float a = smoothstep(0.5, 1.0, fbm(ray * 0.00025 * CLOUD_DENSITY));
vec3 localcolor = mix(vec3(1.1, 1.05, 1.0), vec3(0.3, 0.3, 0.2), a);
a = (1.0 - sum.a) * a;
sum += vec4(localcolor * a, a);
}
}
float a = smoothstep(0.7, 1.0, sum.a);
sum.rgb /= sum.a + 0.0001;
float sundot = clamp(dot(fragAt, normalize(vec3(0.1, 0.25, 0.9))), 0.0, 1.0);
vec3 col = 0.8 * (SKYCOLOR.rgb);
col += 0.47 * vec3(1.6, 1.4, 1.0) * pow(sundot, 350.0);
col += 0.4 * vec3(0.8, 0.9, 1.0) * pow(sundot, 2.0);
sum.rgb -= 0.6 * vec3(0.8, 0.75, 0.7) * pow(sundot, 13.0) * a;
sum.rgb += 0.2 * vec3(1.3, 1.2, 1.0) * pow(sundot, 5.0) * (1.0 - a);
col = mix(col, sum.rgb, sum.a);
if (nmode) col *= 0.2;
gl_FragColor = vec4(col, alpha);
}
